#!/bin/sh
# Fetches the archive rounds' public corpora into /corpus, a volume: LogHub's
# datasets from Zenodo, each checked against the MD5 Zenodo lists, and two
# TSBS DevOps corpora generated by its pinned generator with a fixed seed.
# A corpus is fetched, never committed.
#
#   docker run --rm -v tinystore-corpus:/corpus -v <release-bench>:/src:ro golang:1.27-trixie sh /src/fetch-corpus.sh
set -eu
command -v unzip > /dev/null || { apt-get update -qq && apt-get install -y -qq unzip > /dev/null; }
mkdir -p /corpus/loghub /corpus/tsbs
cd /corpus/loghub
while read -r name md5; do
	[ -f "$name" ] || curl -sSfL -o "$name" "https://zenodo.org/records/8196385/files/$name?download=1"
	echo "$md5  $name" | md5sum -c --quiet -
	dir=${name%%.*}
	if [ ! -d "$dir" ]; then
		mkdir -p "$dir"
		case "$name" in
		*.zip) (cd "$dir" && unzip -q "../$name") ;;
		*.tar.gz) tar -xzf "$name" -C "$dir" ;;
		esac
	fi
done <<'EOF'
Apache.tar.gz de9a42d12f9b60612631c67a5a9f8628
HealthApp.tar.gz cec2cca71da9c4f8e33eaa9b215f1b90
Linux.tar.gz 6d1802d7778126f21c001c6aa7b6b106
Mac.tar.gz e5d0558b6ec661c739e77c7ff1b71498
OpenStack.tar.gz 66bd42c07837a094d9b0ea2d036b5713
Proxifier.tar.gz 2612fce12cc3d16599ddb3db8e9c477a
SSH.tar.gz a44e40b4348697dabf2bba56885e0a38
Zookeeper.tar.gz 11458b4f9fa0911c238f5c1189d4f2d4
HPC.zip 15b3bcf44cf5c98e35451efa22a0de77
Hadoop.zip 34e28a9943704fd54933e2b455829fcc
Android_v1.zip 3b35b3cc00d577a510cf9f416d59b3b3
BGL.zip 4452953c470f2d95fcb32d5f6e733f7a
HDFS_v1.zip 76a24b4d9a6164d543fb275f89773260
EOF
find /corpus/loghub -name '*.log' -size +1k -exec ls -l {} + | awk '{print $5, $9}' > /corpus/loghub/files.txt
sha256sum $(awk '{print $2}' /corpus/loghub/files.txt) > /corpus/loghub/sha256.txt

# the generator is pinned, as research's earlier TSBS rounds pinned it
revision=8323e59c74027b108f4ad5ec5d3e498b0101a02e
if [ ! -x /corpus/tsbs/gen ]; then
	git clone -q https://github.com/timescale/tsbs /tmp/tsbs
	(cd /tmp/tsbs && git checkout -q "$revision" && go build -o /corpus/tsbs/gen ./cmd/tsbs_generate_data)
fi
cd /corpus/tsbs
# wide and short: the 5,090,400 samples of the 2026-09 rounds
[ -f wide.lp ] || ./gen --use-case=devops --seed=123 --scale=20 --log-interval=10s \
	--timestamp-start=2026-01-01T00:00:00Z --timestamp-end=2026-01-01T07:00:00Z --format=influx --file=wide.lp
# narrow and long: ten hosts for three days
[ -f long.lp ] || ./gen --use-case=devops --seed=123 --scale=10 --log-interval=10s \
	--timestamp-start=2026-01-01T00:00:00Z --timestamp-end=2026-01-04T00:00:00Z --format=influx --file=long.lp
sha256sum wide.lp long.lp > sha256.txt
ls -l /corpus/tsbs
